SELECT COUNT(*) FROM users as u, comments as c, postLinks as pl, postHistory as ph, badges as b, posts as p WHERE c.UserId = u.Id AND p.Id = c.PostId AND p.Id = ph.PostId AND b.UserId = u.Id AND p.Id = pl.RelatedPostId AND c.CreationDate>=CAST('2010-08-01 19:11:47' AS TIMESTAMP) AND c.CreationDate<=CAST('2014-09-11 13:42:51' AS TIMESTAMP) AND pl.LinkTypeId=1 AND b."Date"<=CAST('2014-08-02 12:24:29' AS TIMESTAMP)
